const incoming = $input.first().json;
const body = incoming.body ?? incoming;

function flatten(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value.trim();

  if (Array.isArray(value)) {
    return value
      .map((entry, index) => {
        if (typeof entry === 'string') return `${index + 1}. ${entry}`;
        if (entry == null) return '';

        const parts = [
          entry.gap,
          entry.research_gap,
          entry.researchGap,
          entry.description,
          entry.statement,
          entry.text,
          entry.title
        ].filter(Boolean);

        return parts.length ? `${index + 1}. ${parts.join(' - ')}` : JSON.stringify(entry);
      })
      .filter(Boolean)
      .join('\n');
  }

  if (typeof value === 'object') {
    const parts = [
      value.title,
      value.rationale,
      value.gap,
      value.gaps,
      value.researchGap,
      value.research_gap,
      value.description,
      value.statement,
      value.text
    ].filter(Boolean);

    return parts.length ? parts.map(flatten).join('\n') : JSON.stringify(value);
  }

  return String(value).trim();
}

const baselineSource =
  body.baseline ??
  body.researchBaseline ??
  body.semanticBaseline ??
  body.catalystBaseline ??
  body.catalyst_baseline ??
  {};

const title = flatten(
  baselineSource.title ??
  baselineSource.researchTitle ??
  baselineSource.research_title ??
  body.title ??
  body.researchTitle
);

const rationale = flatten(
  baselineSource.rationale ??
  baselineSource.researchRationale ??
  baselineSource.research_rationale ??
  body.rationale
);

const gaps = flatten(
  baselineSource.gaps ??
  baselineSource.gap ??
  baselineSource.researchGaps ??
  baselineSource.research_gaps ??
  baselineSource.researchGap ??
  baselineSource.research_gap ??
  body.gaps ??
  body.gap
);

const rawText = String(
  body.extracted_text ??
  body.extractedText ??
  body.text ??
  body.documentText ??
  body.document_text ??
  body.body?.extracted_text ??
  body.body?.text ??
  ''
).trim();

if (!rawText) {
  throw new Error('No extracted text found. Expected extracted_text, extractedText, text, documentText, or document_text.');
}

if (!title && !rationale && !gaps) {
  throw new Error('No research baseline found. Expected body.baseline with title/rationale/gaps or equivalent fields.');
}

return [{
  json: {
    baseline: {
      title,
      rationale,
      gaps
    },
    raw_extracted_text: rawText,
    meta: {
      documentId: body.documentId ?? body.document_id ?? body.id ?? null,
      filename: body.filename ?? body.fileName ?? body.file_name ?? null,
      source: 'citewise-n8n-semantic-evaluator-v2.5-fatal-topic-mismatch',
      rawCharacters: rawText.length
    }
  }
}];

const item = $input.first().json;

const baseline = item.baseline ?? {};
const rawText = String(item.raw_extracted_text ?? '').trim();

const MAX_CHARS_TO_AI = 9000;
const MAX_SELECTED_CHUNKS = 6;
const CHUNK_SIZE = 1000;
const CHUNK_OVERLAP = 100;

function normalize(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const stopwords = new Set([
  'about', 'above', 'after', 'again', 'against', 'among', 'based', 'because',
  'before', 'being', 'below', 'between', 'could', 'during', 'early', 'field',
  'first', 'found', 'from', 'have', 'having', 'into', 'more', 'most', 'other',
  'paper', 'research', 'result', 'results', 'should', 'study', 'studies',
  'system', 'than', 'their', 'there', 'these', 'this', 'those', 'through',
  'using', 'where', 'which', 'while', 'within', 'with', 'would'
]);

const baselineText = [baseline.title, baseline.rationale, baseline.gaps]
  .filter(Boolean)
  .join(' ');

const keywords = [...new Set(
  normalize(baselineText)
    .split(/\s+/)
    .filter(w => w.length >= 5 && !stopwords.has(w))
)].slice(0, 70);

function splitToCandidateChunks(text) {
  const clean = String(text ?? '').replace(/\r/g, '').trim();
  let paragraphs = clean
    .split(/\n\s*\n+/)
    .map(p => p.replace(/\s+/g, ' ').trim())
    .filter(p => p.length >= 120);

  const chunks = [];

  if (paragraphs.length >= 8) {
    for (let i = 0; i < paragraphs.length; i++) {
      const p = paragraphs[i];
      if (p.length <= CHUNK_SIZE * 1.4) {
        chunks.push({ text: p, originalOrder: i + 1 });
      } else {
        for (let j = 0; j < p.length; j += (CHUNK_SIZE - CHUNK_OVERLAP)) {
          const part = p.slice(j, j + CHUNK_SIZE).trim();
          if (part.length >= 120) chunks.push({ text: part, originalOrder: i + 1 });
        }
      }
    }
    return chunks;
  }

  const flat = clean.replace(/\s+/g, ' ').trim();
  for (let i = 0; i < flat.length; i += (CHUNK_SIZE - CHUNK_OVERLAP)) {
    const part = flat.slice(i, i + CHUNK_SIZE).trim();
    if (part.length >= 120) chunks.push({ text: part, originalOrder: Math.floor(i / (CHUNK_SIZE - CHUNK_OVERLAP)) + 1 });
  }
  return chunks;
}

const candidates = splitToCandidateChunks(rawText);

function chunkScore(chunkObj, index) {
  const chunk = chunkObj.text;
  const lower = normalize(chunk);
  const keywordHits = keywords.filter(k => lower.includes(k)).length;

  const exactPhraseSignals = [
    baseline.title,
    ...(String(baseline.gaps ?? '').split(/[.;\n•]+/).filter(Boolean))
  ]
    .map(normalize)
    .filter(x => x.length >= 20)
    .some(phrase => lower.includes(phrase.slice(0, Math.min(80, phrase.length)))) ? 8 : 0;

  const gapSignal =
    /\b(gap|limitation|limited|lack|absence|challenge|problem|future work|future research|understudied|unexplored|need for|however|despite|although|unresolved|insufficient)\b/i.test(chunk)
      ? 5
      : 0;

  const methodSignal =
    /\b(method|methodology|framework|model|architecture|algorithm|dataset|evaluation|metric|experiment|prototype|implementation|testing|validation|benchmark|protocol)\b/i.test(chunk)
      ? 4
      : 0;

  const theorySignal =
    /\b(theory|theoretical|conceptual|framework|constructivism|connectivism|governance|ethic|ethical|bias|integrity)\b/i.test(chunk)
      ? 3
      : 0;

  const citationSignal =
    /\b(doi|references|bibliography|journal|conference|proceedings|et al\.|volume|issue|publisher|issn|isbn)\b/i.test(chunk)
      ? 2
      : 0;

  const sectionSignal =
    /\b(abstract|introduction|background|related work|literature review|discussion|conclusion|recommendations)\b/i.test(chunk)
      ? 2
      : 0;

  const earlySignal = index < 10 ? 1 : 0;

  return keywordHits * 6 + exactPhraseSignals + gapSignal + methodSignal + theorySignal + citationSignal + sectionSignal + earlySignal;
}

const ranked = candidates
  .map((chunkObj, index) => ({
    chunk: chunkObj.text,
    originalOrder: chunkObj.originalOrder,
    index,
    score: chunkScore(chunkObj, index)
  }))
  .sort((a, b) => b.score - a.score || a.index - b.index);

let selected = ranked
  .slice(0, MAX_SELECTED_CHUNKS)
  .sort((a, b) => a.index - b.index);

if (!selected.length) {
  selected = candidates.slice(0, Math.min(MAX_SELECTED_CHUNKS, candidates.length)).map((x, index) => ({    chunk: x.text,
    originalOrder: x.originalOrder,
    index,
    score: 0
  }));
}

let finalText = selected
  .map((x, i) => `[CHUNK ${i + 1} | original_order=${x.originalOrder} | relevance_hint=${x.score}]\n${x.chunk}`)
  .join('\n\n---CHUNK BREAK---\n\n');

if (finalText.length > MAX_CHARS_TO_AI) {
  finalText = finalText.slice(0, MAX_CHARS_TO_AI);
}

return [{
  json: {
    baseline,
    extracted_text: finalText,
    raw_extracted_text: rawText,
    meta: item.meta ?? {},
    chunkStats: {
      rawCharacters: rawText.length,
      candidateChunks: candidates.length,
      selectedChunks: selected.length,
      selectedCharacters: finalText.length,
      keywordCount: keywords.length,
      maxCharsToAi: MAX_CHARS_TO_AI,
      workflowVersion: 'semantic-scoring-v2.5-fatal-topic-mismatch-override'
    }
  }
}];

const item = $input.first().json;

let raw =
  item.output ??
  item.text ??
  item.response ??
  item.message?.content ??
  item.content;

if (raw == null) {
  throw new Error('No LLM text found. Keys on item: ' + Object.keys(item).join(', '));
}

raw = String(raw)
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');

if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
  throw new Error('LLM did not return a JSON object. Raw output: ' + raw.slice(0, 500));
}

let parsed;
try {
  parsed = JSON.parse(raw.slice(firstBrace, lastBrace + 1));
} catch (error) {
  throw new Error('LLM returned invalid JSON. Parse error: ' + error.message + '. Raw output: ' + raw.slice(0, 500));
}

const validationFlags = [];

function clampScore(value, fieldName) {
  const n = Number(value);
  if (!Number.isFinite(n)) {
    validationFlags.push(`${fieldName} missing or invalid; defaulted to 0`);
    return 0;
  }

  const rounded = Math.round(n);
  if (rounded < 0 || rounded > 100) {
    validationFlags.push(`${fieldName} was outside 0-100 and was clamped`);
  }

  return Math.max(0, Math.min(100, rounded));
}

function cleanStringArray(value, fieldName, maxItems = 8) {
  if (!Array.isArray(value)) {
    validationFlags.push(`${fieldName} missing or invalid; defaulted to []`);
    return [];
  }

  return value
    .map(v => String(v ?? '').trim())
    .filter(Boolean)
    .slice(0, maxItems);
}

const allowedConfidence = ['High', 'Medium', 'Low'];
let confidenceLevel = String(parsed.confidenceLevel ?? '').trim();
if (!allowedConfidence.includes(confidenceLevel)) {
  validationFlags.push('confidenceLevel missing or invalid; defaulted to Low');
  confidenceLevel = 'Low';
}

const allowedRelevance = ['High', 'Medium', 'Low'];

function normalizeCriterion(value, fieldName, index) {
  const rawCriterion = String(value ?? '').trim();
  const key = rawCriterion.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

  if (!key) {
    validationFlags.push(`${fieldName}[${index}].criterion missing; defaulted to Gap Alignment`);
    return 'Gap Alignment';
  }

  if (key.includes('gap')) return 'Gap Alignment';
  if (key.includes('method') || key.includes('evaluation') || key.includes('benchmark') || key.includes('protocol')) return 'Methodology';
  if (key.includes('theor') || key.includes('framework') || key.includes('architecture') || key.includes('governance') || key.includes('conceptual')) return 'Theory';
  if (key.includes('citation') || key.includes('source') || key.includes('reference')) return 'Citation Quality';

  validationFlags.push(`${fieldName}[${index}].criterion "${rawCriterion}" was normalized to Gap Alignment`);
  return 'Gap Alignment';
}

function parseExcerptArray(value, fieldName, defaultEvidenceType, maxItems = 8) {
  if (!Array.isArray(value)) return [];

  return value
    .map((e, index) => {
      const criterion = normalizeCriterion(e.criterion, fieldName, index);

      const relevanceLevel = allowedRelevance.includes(String(e.relevanceLevel))
        ? String(e.relevanceLevel)
        : 'Low';

      if (!allowedRelevance.includes(String(e.relevanceLevel))) {
        validationFlags.push(`${fieldName}[${index}].relevanceLevel invalid; defaulted to Low`);
      }

      let evidenceType = String(e.evidenceType ?? defaultEvidenceType ?? '').trim().toLowerCase();
      if (!['supporting', 'weakness', 'mismatch'].includes(evidenceType)) {
        evidenceType = defaultEvidenceType;
        validationFlags.push(`${fieldName}[${index}].evidenceType invalid; defaulted to ${defaultEvidenceType}`);
      }

      return {
        criterion,
        quoteText: String(e.quoteText ?? '').replace(/\s+/g, ' ').trim(),
        pageNumber: Number.isFinite(Number(e.pageNumber)) ? Number(e.pageNumber) : 1,
        relevanceLevel,
        evidenceType
      };
    })
    .filter(e => e.quoteText.length > 0)
    .slice(0, maxItems);
}

let evidence = parseExcerptArray(parsed.evidenceExcerpts, 'evidenceExcerpts', 'supporting', 6);
let diagnosticEvidence = parseExcerptArray(parsed.diagnosticEvidenceExcerpts, 'diagnosticEvidenceExcerpts', 'weakness', 6);

if (!Array.isArray(parsed.evidenceExcerpts)) {
  validationFlags.push('evidenceExcerpts missing or invalid; defaulted to []');
}

// Safety rule: evidenceExcerpts must be supporting evidence only.
const movedDiagnostics = evidence.filter(e => e.evidenceType !== 'supporting');
if (movedDiagnostics.length > 0) {
  validationFlags.push('Non-supporting excerpts were moved out of evidenceExcerpts into diagnosticEvidenceExcerpts');
  diagnosticEvidence = [...diagnosticEvidence, ...movedDiagnostics].slice(0, 8);
}

evidence = evidence.filter(e => e.evidenceType === 'supporting');

// If Gemini accidentally placed a supporting excerpt in diagnosticEvidenceExcerpts, rescue it.
const rescuedSupporting = diagnosticEvidence.filter(e => e.evidenceType === 'supporting');
if (rescuedSupporting.length > 0) {
  validationFlags.push('Supporting excerpts found in diagnosticEvidenceExcerpts were moved into evidenceExcerpts');
  evidence = [...evidence, ...rescuedSupporting].slice(0, 8);
  diagnosticEvidence = diagnosticEvidence.filter(e => e.evidenceType !== 'supporting');
}

return [{
  json: {
    gapAlignmentScore: clampScore(parsed.gapAlignmentScore, 'gapAlignmentScore'),
    methodologyScore: clampScore(parsed.methodologyScore, 'methodologyScore'),
    theoreticalScore: clampScore(parsed.theoreticalScore, 'theoreticalScore'),
    citationScore: clampScore(parsed.citationScore, 'citationScore'),
    confidenceLevel,
    mismatchFlags: cleanStringArray(parsed.mismatchFlags, 'mismatchFlags'),
    weaknessFlags: cleanStringArray(parsed.weaknessFlags, 'weaknessFlags'),
    evidenceExcerpts: evidence,
    diagnosticEvidenceExcerpts: diagnosticEvidence,
    validationFlags,
    rawAiResponse: raw.slice(firstBrace, lastBrace + 1)
  }
}];

const ai = $input.first().json;

const source = $('Select Relevant Text Chunks1').first().json;
const rawText = String(source.raw_extracted_text ?? source.extracted_text ?? '');
const baseline = source.baseline ?? {};
const meta = source.meta ?? {};

const WEIGHTS = {
  gap: 0.35,
  methodology: 0.30,
  theory: 0.20,
  citation: 0.15
};

const THRESHOLDS = {
  recommendedOverall: 80,
  recommendedGapMinimum: 75,
  recommendedMethodologyMinimum: 70,
  recommendedTheoryMinimum: 50,
  recommendedCitationMinimum: 60,
  needsReviewOverall: 50,
  lowGapMinimum: 40,
  lowCitationMinimum: 35
};

const SEVERE_MISMATCH_FLAGS = new Set([
  'TOPIC_MISMATCH',
  'GAP_CONTRADICTION',
  'POPULATION_CONTEXT_MISMATCH',
  'PREDATORY_VENUE_FLAG',
  'UNVERIFIABLE_SOURCE_FLAG'
]);

const WEAKNESS_PENALTIES = {
  NO_EXPLICIT_GAP_STATEMENT: 3,
  WEAK_RATIONALE_LINK: 2,
  SUMMARY_ONLY_NO_SYNTHESIS: 3,
  NO_METHOD_JUSTIFICATION: 3,
  NO_EVALUATION_METRICS: 4,
  AD_HOC_TESTING_ONLY: 5,
  NO_THEORY_OR_FRAMEWORK: 2,
  FRAMEWORK_NAMED_NOT_USED: 2,
  LOW_PEER_REVIEW_SHARE: 4,
  OLD_SOURCE_HEAVY: 2,
  MISSING_DOIS_OR_STABLE_IDS: 2,
  APA_IEEE_ACM_STYLE_ERRORS: 1,
  REFERENCES_MISSING_OR_UNCLEAR: 4
};

function clamp(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(100, Math.round(n)));
}

function normalize(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeForMatch(s) {
  return normalize(s)
    .replace(/\.\.\./g, ' ')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function quoteMatches(text, quote) {
  const q = normalizeForMatch(quote);
  const t = normalizeForMatch(text);
  if (q.length < 20) return false;
  if (t.includes(q)) return true;

  // Accept quotes with line-break or ellipsis differences if enough substantial fragments match.
  const fragments = q
    .split(/\s*(?:\.\.\.|;|:)\s*/)
    .map(x => x.trim())
    .filter(x => x.length >= 28);

  if (fragments.length > 0 && fragments.some(f => t.includes(f))) return true;

  // Token fallback: conservative enough to rescue short paraphrase-free snippets with PDF extraction noise.
  const stop = new Set(['the','and','for','that','with','from','this','these','those','into','onto','are','was','were','been','being','have','has','had','their','which','while','through','between','using','used','use','also','such','within','system','systems','paper','study','research']);
  const tokens = [...new Set(q.split(/\s+/).filter(w => w.length >= 5 && !stop.has(w)))];
  if (tokens.length < 5) return false;
  const hits = tokens.filter(tok => t.includes(tok)).length;
  return hits >= Math.min(7, Math.ceil(tokens.length * 0.65));
}

function uniqStrings(values, maxItems = 30) {
  return [...new Set(
    (Array.isArray(values) ? values : [])
      .map(v => String(v ?? '').trim())
      .filter(Boolean)
  )].slice(0, maxItems);
}

function pushUnique(array, value) {
  if (value && !array.includes(value)) array.push(value);
}

function removeFlag(array, value) {
  return array.filter(flag => flag !== value);
}

function normalizeCriterion(value) {
  const rawCriterion = String(value ?? '').trim();
  const key = rawCriterion.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (key.includes('gap')) return 'Gap Alignment';
  if (key.includes('method') || key.includes('evaluation') || key.includes('benchmark') || key.includes('protocol')) return 'Methodology';
  if (key.includes('theor') || key.includes('framework') || key.includes('architecture') || key.includes('governance') || key.includes('conceptual')) return 'Theory';
  if (key.includes('citation') || key.includes('reference') || key.includes('source')) return 'Citation Quality';
  return 'Gap Alignment';
}

const stopwords = new Set([
  'about', 'above', 'after', 'again', 'against', 'among', 'based', 'because',
  'before', 'being', 'below', 'between', 'could', 'during', 'early', 'field',
  'first', 'found', 'from', 'have', 'having', 'into', 'more', 'most', 'other',
  'paper', 'research', 'result', 'results', 'should', 'study', 'studies',
  'system', 'than', 'their', 'there', 'these', 'this', 'those', 'through',
  'using', 'where', 'which', 'while', 'within', 'with', 'would'
]);

const baselineText = [baseline.title, baseline.rationale, baseline.gaps].filter(Boolean).join(' ');
const baselineKeywords = [...new Set(
  normalize(baselineText)
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length >= 5 && !stopwords.has(w))
)].slice(0, 100);

function keywordHits(text) {
  const lower = normalize(text);
  return baselineKeywords.filter(k => lower.includes(k)).length;
}

const validationFlags = uniqStrings(ai.validationFlags ?? [], 30);
const originalEvidence = Array.isArray(ai.evidenceExcerpts) ? ai.evidenceExcerpts : [];
const originalDiagnostic = Array.isArray(ai.diagnosticEvidenceExcerpts) ? ai.diagnosticEvidenceExcerpts : [];

// Rescue any supporting excerpt accidentally returned under diagnosticEvidenceExcerpts.
const evidenceCandidates = [
  ...originalEvidence,
  ...originalDiagnostic.filter(e => String(e.evidenceType ?? '').toLowerCase() === 'supporting')
];

const diagnosticCandidates = originalDiagnostic.filter(e => String(e.evidenceType ?? '').toLowerCase() !== 'supporting');

const verifiedEvidence = evidenceCandidates
  .map(e => ({
    criterion: normalizeCriterion(e.criterion),
    quoteText: String(e.quoteText ?? '').replace(/\s+/g, ' ').trim(),
    pageNumber: Number.isFinite(Number(e.pageNumber)) ? Number(e.pageNumber) : 1,
    relevanceLevel: ['High', 'Medium', 'Low'].includes(String(e.relevanceLevel)) ? String(e.relevanceLevel) : 'Low',
    evidenceType: 'supporting'
  }))
  .filter(e => e.quoteText.length > 0)

  .slice(0, 8);

const verifiedDiagnosticEvidence = diagnosticCandidates
  .map(e => ({
    criterion: normalizeCriterion(e.criterion),
    quoteText: String(e.quoteText ?? '').replace(/\s+/g, ' ').trim(),
    pageNumber: Number.isFinite(Number(e.pageNumber)) ? Number(e.pageNumber) : 1,
    relevanceLevel: ['High', 'Medium', 'Low'].includes(String(e.relevanceLevel)) ? String(e.relevanceLevel) : 'Low',
    evidenceType: ['weakness', 'mismatch'].includes(String(e.evidenceType).toLowerCase()) ? String(e.evidenceType).toLowerCase() : 'weakness'
  }))
  .filter(e => e.quoteText.length > 0)

  .slice(0, 8);

if (verifiedEvidence.length < evidenceCandidates.length) {
  pushUnique(validationFlags, 'Some AI supporting evidence excerpts were removed because they were not found in extracted text');
}

if (verifiedDiagnosticEvidence.length < diagnosticCandidates.length) {
  pushUnique(validationFlags, 'Some diagnostic evidence excerpts were removed because they were not found in extracted text');
}

let gap = clamp(ai.gapAlignmentScore);
let methodology = clamp(ai.methodologyScore);
let theoretical = clamp(ai.theoreticalScore);
let citation = clamp(ai.citationScore);
let mismatchFlags = uniqStrings(ai.mismatchFlags ?? [], 20);
let weaknessFlags = uniqStrings(ai.weaknessFlags ?? [], 30);

const supportingEvidence = verifiedEvidence.filter(e => e.evidenceType === 'supporting');
const diagnosticEvidence = verifiedDiagnosticEvidence.filter(e => e.evidenceType === 'weakness' || e.evidenceType === 'mismatch');

const gapEvidence = supportingEvidence.filter(e => e.criterion === 'Gap Alignment' && ['High', 'Medium'].includes(e.relevanceLevel));
const methodologyEvidence = supportingEvidence.filter(e => e.criterion === 'Methodology' && ['High', 'Medium'].includes(e.relevanceLevel));
const theoryEvidence = supportingEvidence.filter(e => e.criterion === 'Theory' && ['High', 'Medium'].includes(e.relevanceLevel));
const citationEvidence = supportingEvidence.filter(e => e.criterion === 'Citation Quality');

const highEvidenceCount = supportingEvidence.filter(e => e.relevanceLevel === 'High').length;
const evidenceKeywordHits = keywordHits(supportingEvidence.map(e => e.quoteText).join(' '));
const rawLower = normalize(rawText);

const methodSignalInText = /\b(method|methodology|framework|benchmark|protocol|evaluation|metric|dataset|algorithm|architecture|experiment|implementation|workflow|task|testing|validation|retrieval|reranking|synthesis)\b/i.test(rawText);
const theorySignalInText = /\b(theory|theoretical|conceptual|framework|architecture|governance|ethical|ethics|citation-aware|source-tracking|source tracking|design framework|model|protocol|pipeline)\b/i.test(rawText);
const relatedRagSignal = /\b(agentic|rag|retrieval augmented generation|retrieval-augmented generation|citation-aware|scientific literature|academic synthesis|benchmark|hallucination|source attribution|source tracking|source-tracking)\b/i.test(rawText);

// Remove weakness flags contradicted by verified evidence.
if (gapEvidence.length > 0) {
  weaknessFlags = removeFlag(weaknessFlags, 'NO_EXPLICIT_GAP_STATEMENT');
}
if (methodologyEvidence.length > 0) {
  weaknessFlags = removeFlag(weaknessFlags, 'NO_METHOD_JUSTIFICATION');
}
if (methodologyEvidence.length > 0 || /\b(metric|benchmark|evaluation|experiment|accuracy|dataset|test|testing|validation)\b/i.test(rawText)) {
  weaknessFlags = removeFlag(weaknessFlags, 'NO_EVALUATION_METRICS');
}
if (theoryEvidence.length > 0 || theorySignalInText) {
  weaknessFlags = removeFlag(weaknessFlags, 'NO_THEORY_OR_FRAMEWORK');
}

if (supportingEvidence.length === 0) {




  pushUnique(weaknessFlags, 'NO_EXPLICIT_GAP_STATEMENT');
  pushUnique(weaknessFlags, 'NO_METHOD_JUSTIFICATION');
  pushUnique(weaknessFlags, 'NO_THEORY_OR_FRAMEWORK');
  pushUnique(validationFlags, 'All scores capped because no verified supporting evidence excerpts were found');
}

if (gapEvidence.length === 0) {

  pushUnique(weaknessFlags, 'NO_EXPLICIT_GAP_STATEMENT');
  pushUnique(validationFlags, 'Gap Alignment capped because no credible supporting gap evidence was verified');
} else if (gapEvidence.length < 2) {

  pushUnique(validationFlags, 'Gap Alignment capped at 74 because one supporting gap evidence item was verified');
}

if (methodologyEvidence.length === 0) {
  if (methodSignalInText && gapEvidence.length > 0 && relatedRagSignal) {

    pushUnique(validationFlags, 'Methodology capped at 64 because method signals were present but no exact methodology excerpt was verified');
  } else {

    pushUnique(weaknessFlags, 'NO_METHOD_JUSTIFICATION');
    pushUnique(validationFlags, 'Methodology capped because no credible supporting methodology evidence was verified');
