} else if (methodologyEvidence.length < 2) {

  pushUnique(validationFlags, 'Methodology capped at 74 because one supporting methodology evidence item was verified');
}

if (theoryEvidence.length === 0) {
  if (theorySignalInText && relatedRagSignal) {

    pushUnique(validationFlags, 'Theory/Framework capped at 64 because framework/architecture signals were present but no exact theory excerpt was verified');
  } else {

    pushUnique(weaknessFlags, 'NO_THEORY_OR_FRAMEWORK');
    pushUnique(validationFlags, 'Theory/Framework capped at 39 because no explicit framework evidence was verified');
  }
} else if (theoryEvidence.length < 2) {

}

if (weaknessFlags.includes('FRAMEWORK_NAMED_NOT_USED')) {

  pushUnique(validationFlags, 'Theory/Framework capped at 64 because the framework was named but not strongly used');
}

if (weaknessFlags.includes('NO_EVALUATION_METRICS') && methodologyEvidence.length === 0) {

  pushUnique(validationFlags, 'Methodology capped at 64 because evaluation was claimed but no metric/tool/test evidence was verified');
}

if (weaknessFlags.includes('AD_HOC_TESTING_ONLY')) {
  methodology = Math.min(methodology, 59);
  pushUnique(validationFlags, 'Methodology capped at 59 because testing appeared ad hoc only');
}

const hasReferenceListSignal = /\b(references|bibliography|works cited|literature cited)\b/i.test(rawText);
const hasAcademicCitationSignals = /\b(doi|journal|conference|proceedings|volume|issue|publisher|issn|isbn|et al\.|abstract|keywords|arxiv)\b/i.test(rawText);

if (!hasReferenceListSignal && !hasAcademicCitationSignals) {

  pushUnique(weaknessFlags, 'REFERENCES_MISSING_OR_UNCLEAR');
  pushUnique(validationFlags, 'Citation Quality capped at 49 because reference/citation signals were missing or unclear');
}

if (weaknessFlags.includes('LOW_PEER_REVIEW_SHARE')) {

  pushUnique(validationFlags, 'Citation Quality capped at 64 because peer-reviewed/source authority signals were weak');
}

if (weaknessFlags.includes('MISSING_DOIS_OR_STABLE_IDS')) {
  citation = Math.min(citation, 89);
}

if (gapEvidence.length > 0 && evidenceKeywordHits === 0) {
  gap = Math.min(gap, 59);
  pushUnique(weaknessFlags, 'WEAK_RATIONALE_LINK');
  pushUnique(validationFlags, 'Gap score capped because verified supporting evidence did not share meaningful baseline terms');
} else if (gapEvidence.length > 0 && evidenceKeywordHits < 2) {

  pushUnique(validationFlags, 'Gap score capped because verified supporting evidence had limited baseline keyword overlap');
}

const mismatchText = [
  ...mismatchFlags,
  ...diagnosticEvidence.filter(e => e.evidenceType === 'mismatch').map(e => e.quoteText)
].join(' ');

// GAP_TYPE_MISMATCH and METHOD_MISMATCH are not automatically fatal if verified supporting RAG/benchmark evidence exists.
const hasSevereEnumMismatch = mismatchFlags.some(flag => SEVERE_MISMATCH_FLAGS.has(flag));
const hasMethodMismatchFatal = mismatchFlags.includes('METHOD_MISMATCH') && methodologyEvidence.length === 0 && !methodSignalInText;
const hasGapTypeMismatchFatal = mismatchFlags.includes('GAP_TYPE_MISMATCH') && gapEvidence.length === 0;
const hasTextFatalMismatch = /\b(critical|unrelated|not related|does not address|no connection|wrong population|different population|different domain|different field|different problem|outside scope|contradicts|already solved)\b/i.test(mismatchText);
const hasFatalMismatch = hasSevereEnumMismatch || hasMethodMismatchFatal || hasGapTypeMismatchFatal || hasTextFatalMismatch;

// Fatal Topic Mismatch Override:
// A paper can have citation/reference quality, but if it is topically unrelated to
// the CATalyst baseline and has no verified supporting evidence, it should not
// receive semantic relevance credit.
const fatalTopicMismatchNoSupport =
  mismatchFlags.includes('TOPIC_MISMATCH') &&
  supportingEvidence.length === 0;

if (fatalTopicMismatchNoSupport) {




  // Keep Citation Quality as a diagnostic signal only; it must not affect overall relevance.
  citation = Math.min(citation, 30);

  pushUnique(validationFlags, 'Overall score set to 0 because TOPIC_MISMATCH was detected with no verified supporting evidence');
  pushUnique(validationFlags, 'Citation Quality retained only as a diagnostic signal and excluded from overall relevance due to fatal topic mismatch');
} else if (hasFatalMismatch) {
  gap = Math.min(gap, 45);
  pushUnique(validationFlags, 'Gap score capped because a fatal or critical mismatch was detected');
}

let confidenceLevel = ['High', 'Medium', 'Low'].includes(String(ai.confidenceLevel))
  ? String(ai.confidenceLevel)
  : 'Low';

function downgradeConfidence(current, target) {
  const rank = { High: 3, Medium: 2, Low: 1 };
  return rank[target] < rank[current] ? target : current;
}

if (fatalTopicMismatchNoSupport || hasFatalMismatch || gapEvidence.length === 0) {
  confidenceLevel = downgradeConfidence(confidenceLevel, 'Low');
} else if (validationFlags.length >= 5 || highEvidenceCount === 0 || evidenceKeywordHits < 2 || methodologyEvidence.length === 0) {
  confidenceLevel = downgradeConfidence(confidenceLevel, 'Medium');
}

const confidenceScore = confidenceLevel === 'High' ? 0.85 : confidenceLevel === 'Medium' ? 0.65 : 0.45;

function calculateWeaknessPenalty(flags) {
  const unique = uniqStrings(flags, 50);
  const total = unique.reduce((sum, flag) => sum + (WEAKNESS_PENALTIES[flag] ?? 0), 0);
  return Math.min(total, 12);
}

const weaknessPenalty = calculateWeaknessPenalty(weaknessFlags);

let overallScore = Math.round(
  gap * WEIGHTS.gap +
  methodology * WEIGHTS.methodology +
  theoretical * WEIGHTS.theory +
  citation * WEIGHTS.citation
) - weaknessPenalty;

if (fatalTopicMismatchNoSupport) {

} else if (hasFatalMismatch) {

}
overallScore = Math.max(0, Math.min(100, overallScore));

const moderateWeaknessCount = weaknessFlags.filter(flag => !SEVERE_MISMATCH_FLAGS.has(flag)).length;

let recommendationStatus;
if (
  fatalTopicMismatchNoSupport ||
  hasFatalMismatch ||
  supportingEvidence.length === 0 ||
  gapEvidence.length === 0 ||
  gap < THRESHOLDS.lowGapMinimum ||
  citation < THRESHOLDS.lowCitationMinimum ||
  overallScore < 40
) {
  recommendationStatus = 'Low Relevance';
} else if (
  overallScore >= THRESHOLDS.recommendedOverall &&
  gap >= THRESHOLDS.recommendedGapMinimum &&
  methodology >= THRESHOLDS.recommendedMethodologyMinimum &&
  theoretical >= THRESHOLDS.recommendedTheoryMinimum &&
  citation >= THRESHOLDS.recommendedCitationMinimum &&
  confidenceScore >= 0.70 &&
  gapEvidence.length >= 2 &&
  methodologyEvidence.length >= 2 &&
  moderateWeaknessCount <= 2
) {
  recommendationStatus = 'Recommended';
} else {
  recommendationStatus = 'Needs Review';
}

const relevanceLevel = recommendationStatus === 'Recommended'
  ? 'High'
  : recommendationStatus === 'Needs Review'
    ? 'Medium'
    : 'Low';

const displayEvidence = supportingEvidence.filter(e =>
  e.evidenceType === 'supporting' &&
  ['High', 'Medium'].includes(e.relevanceLevel)
);

if (supportingEvidence.length > displayEvidence.length) {
  pushUnique(validationFlags, 'Low-relevance supporting excerpts were hidden from evidenceExcerpts display output');
}

return [{
  json: {
    documentId: meta.documentId ?? null,
    filename: meta.filename ?? null,
    scores: {
      gapAlignment: Math.round(gap),
      methodology: Math.round(methodology),
      theory: Math.round(theoretical),
      citationQuality: Math.round(citation),
      overall: overallScore
    },
    gapAlignmentScore: Math.round(gap),
    methodologyScore: Math.round(methodology),
    theoreticalScore: Math.round(theoretical),
    citationScore: Math.round(citation),
    overallScore,
    weaknessPenalty,
    recommendationStatus,
    confidenceScore,
    confidenceLevel,
    relevanceLevel,
    mismatchFlags: uniqStrings(mismatchFlags, 20),
    weaknessFlags: uniqStrings(weaknessFlags, 30),
    validationFlags: uniqStrings(validationFlags, 30),
    evidenceCounts: {
      verifiedSupportingEvidence: supportingEvidence.length,
      verifiedDiagnosticEvidence: diagnosticEvidence.length,
      displayedEvidence: displayEvidence.length,
